def check_single_active_owner(apps, schema_editor):
    User = apps.get_model('accounts', 'User')
    duplicated = (
        User.objects.filter(role='owner', is_active=True)
        .values('tenant_id').annotate(n=Count('id')).filter(n__gt=1)
    )
    problems = []
    for row in duplicated:
        owner_ids = list(
            User.objects.filter(role='owner', is_active=True, tenant_id=row['tenant_id'])
            .values_list('id', flat=True)
        )
        problems.append(f"tenant {row['tenant_id']}: owners {', '.join(str(i) for i in owner_ids)}")
    if problems:
        raise RuntimeError(
            'Cannot enforce one active Owner per tenant (Module 22). Deactivate or re-role the '
            'extra Owner accounts, then migrate again:\n  ' + '\n  '.join(problems)
        )


